1: 'use strict'
2: 
3: const { AsyncResource } = require('node:async_hooks')
4: const { FifoMap: Fifo } = require('toad-cache')
5: const { parse: secureJsonParse } = require('secure-json-parse')
6: const ContentType = require('./content-type')
7: const {
8:   kDefaultJsonParse,
9:   kContentTypeParser,
10:   kBodyLimit,
11:   kRequestPayloadStream,
12:   kState,
13:   kTestInternals,
14:   kReplyIsError,
15:   kRouteContext
16: } = require('./symbols')
17: 
18: const {
19:   FST_ERR_CTP_INVALID_TYPE,
20:   FST_ERR_CTP_EMPTY_TYPE,
21:   FST_ERR_CTP_ALREADY_PRESENT,
22:   FST_ERR_CTP_INVALID_HANDLER,
23:   FST_ERR_CTP_INVALID_PARSE_TYPE,
24:   FST_ERR_CTP_BODY_TOO_LARGE,
25:   FST_ERR_CTP_INVALID_MEDIA_TYPE,
26:   FST_ERR_CTP_INVALID_CONTENT_LENGTH,
27:   FST_ERR_CTP_EMPTY_JSON_BODY,
28:   FST_ERR_CTP_INSTANCE_ALREADY_STARTED,
29:   FST_ERR_CTP_INVALID_JSON_BODY
30: } = require('./errors')
31: const { FSTSEC001 } = require('./warnings')
32: 
33: function ContentTypeParser (bodyLimit, onProtoPoisoning, onConstructorPoisoning) {
34:   this[kDefaultJsonParse] = getDefaultJsonParser(onProtoPoisoning, onConstructorPoisoning)
35:   // using a map instead of a plain object to avoid prototype hijack attacks
36:   this.customParsers = new Map()
37:   this.customParsers.set('application/json', new Parser(true, false, bodyLimit, this[kDefaultJsonParse]))
38:   this.customParsers.set('text/plain', new Parser(true, false, bodyLimit, defaultPlainTextParser))
39:   this.parserList = ['application/json', 'text/plain']
40:   this.parserRegExpList = []
41:   this.cache = new Fifo(100)
42: }
43: 
44: ContentTypeParser.prototype.add = function (contentType, opts, parserFn) {
45:   const contentTypeIsString = typeof contentType === 'string'
46: 
47:   if (contentTypeIsString) {
48:     contentType = contentType.trim().toLowerCase()
49:     if (contentType.length === 0) throw new FST_ERR_CTP_EMPTY_TYPE()
50:   } else if (!(contentType instanceof RegExp)) {
51:     throw new FST_ERR_CTP_INVALID_TYPE()
52:   }
53: 
54:   if (typeof parserFn !== 'function') {
55:     throw new FST_ERR_CTP_INVALID_HANDLER()
56:   }
57: 
58:   if (this.existingParser(contentType)) {
59:     throw new FST_ERR_CTP_ALREADY_PRESENT(contentType)
60:   }
61: 
62:   if (opts.parseAs !== undefined) {
63:     if (opts.parseAs !== 'string' && opts.parseAs !== 'buffer') {
64:       throw new FST_ERR_CTP_INVALID_PARSE_TYPE(opts.parseAs)
65:     }
66:   }
67: 
68:   const parser = new Parser(
69:     opts.parseAs === 'string',
70:     opts.parseAs === 'buffer',
71:     opts.bodyLimit,
72:     parserFn
73:   )
74: 
75:   if (contentType === '*') {
76:     this.customParsers.set('', parser)
77:   } else {
78:     if (contentTypeIsString) {
79:       const ct = new ContentType(contentType)
80:       if (ct.isValid === false) {
81:         throw new FST_ERR_CTP_INVALID_TYPE()
82:       }
83:       const normalizedContentType = ct.toString()
84:       this.parserList.unshift(normalizedContentType)
85:       this.customParsers.set(normalizedContentType, parser)
86:     } else {
87:       validateRegExp(contentType)
88:       this.parserRegExpList.unshift(contentType)
89:       this.customParsers.set(contentType.toString(), parser)
90:     }
91:   }
92: }
93: 
94: ContentTypeParser.prototype.hasParser = function (contentType) {
95:   if (typeof contentType === 'string') {
96:     contentType = new ContentType(contentType).toString()
97:   } else {
98:     if (!(contentType instanceof RegExp)) throw new FST_ERR_CTP_INVALID_TYPE()
99:     contentType = contentType.toString()
100:   }
101: 
102:   return this.customParsers.has(contentType)
103: }
104: 
105: ContentTypeParser.prototype.existingParser = function (contentType) {
106:   if (typeof contentType === 'string') {
107:     const ct = new ContentType(contentType).toString()
108:     if (contentType === 'application/json' && this.customParsers.has(contentType)) {
109:       return this.customParsers.get(ct).fn !== this[kDefaultJsonParse]
110:     }
111:     if (contentType === 'text/plain' && this.customParsers.has(contentType)) {
112:       return this.customParsers.get(ct).fn !== defaultPlainTextParser
113:     }
114:   }
115: 
116:   return this.hasParser(contentType)
117: }
118: 
119: ContentTypeParser.prototype.getParser = function (contentType) {
120:   if (typeof contentType === 'string') {
121:     const cached = this.cache.get(contentType)
122:     if (cached !== undefined) return cached
123:     contentType = new ContentType(contentType)
124:   }
125:   const ct = contentType.toString()
126: 
127:   let parser = this.cache.get(ct)
128:   if (parser !== undefined) return parser
129:   parser = this.customParsers.get(ct)
130:   if (parser !== undefined) {
131:     this.cache.set(ct, parser)
132:     return parser
133:   }
134: 
135:   // We have conflicting desires across our test suite. In some cases, we
136:   // expect to get a parser by just passing the media-type. In others, we expect
137:   // to get a parser registered under the media-type while also providing
138:   // parameters. And in yet others, we expect to register a parser under the
139:   // media-type and have it apply to any request with a header that starts
140:   // with that type.
141:   parser = this.customParsers.get(contentType.mediaType)
142:   if (parser !== undefined) {
143:     this.cache.set(ct, parser)
144:     return parser
145:   }
146: 
147:   for (let j = 0; j !== this.parserRegExpList.length; ++j) {
148:     const parserRegExp = this.parserRegExpList[j]
149:     // A parser registered with a `g`/`y` flagged RegExp keeps a mutable
150:     // lastIndex between calls, so a plain `.test()` would skip part of the
151:     // next content type and match inconsistently. Reset it before testing.
152:     parserRegExp.lastIndex = 0
153:     if (parserRegExp.test(ct)) {
154:       parser = this.customParsers.get(parserRegExp)
155:       this.cache.set(ct, parser)
156:       return parser
157:     }
158:   }
159: 
160:   return this.customParsers.get('')
161: }
162: 
163: ContentTypeParser.prototype.removeAll = function () {
164:   this.customParsers = new Map()
165:   this.parserRegExpList = []
166:   this.parserList = []
167:   this.cache = new Fifo(100)
168: }
169: 
170: ContentTypeParser.prototype.remove = function (contentType) {
171:   let parsers
172: 
173:   if (typeof contentType === 'string') {
174:     contentType = new ContentType(contentType).toString()
175:     parsers = this.parserList
176:   } else {
177:     if (!(contentType instanceof RegExp)) throw new FST_ERR_CTP_INVALID_TYPE()
178:     contentType = contentType.toString()
179:     parsers = this.parserRegExpList
180:   }
181: 
182:   const removed = this.customParsers.delete(contentType)
183:   const idx = parsers.findIndex(ct => ct.toString() === contentType)
184: 
185:   if (idx > -1) {
186:     parsers.splice(idx, 1)
187:   }
188: 
189:   return removed || idx > -1
190: }
191: 
192: ContentTypeParser.prototype.run = function (contentType, handler, request, reply) {
193:   const parser = this.getParser(contentType)
194: 
195:   if (parser === undefined) {
196:     if (request.is404 === true) {
197:       handler(request, reply)
198:       return
199:     }
200: 
201:     reply[kReplyIsError] = true
202:     reply.send(new FST_ERR_CTP_INVALID_MEDIA_TYPE())
203:     return
204:   }
205: 
206:   const resource = new AsyncResource('content-type-parser:run', request)
207: 
208:   // Preserve the request's async context without the per-request function
209:   // properties and wrappers created by AsyncResource.bind().
210:   function done (error, body) {
211:     resource.runInAsyncScope(onDone, undefined, error, body)
212:   }
213: 
214:   if (parser.asString === true || parser.asBuffer === true) {
215:     rawBody(
216:       request,
217:       reply,
218:       reply[kRouteContext]._parserOptions,
219:       parser,
220:       done
221:     )
222:     return
223:   }
224: 
225:   const result = parser.fn(request, request[kRequestPayloadStream], done)
226:   if (result && typeof result.then === 'function') {
227:     result.then(body => { done(null, body) }, done)
228:   }
229: 
230:   function onDone (error, body) {
231:     resource.emitDestroy()
232:     if (error != null) {
233:       // We must close the connection as the client may
234:       // send more data
235:       reply.header('connection', 'close')
236:       reply[kReplyIsError] = true
237:       reply.send(error)
238:       return
239:     }
240:     request.body = body
241:     handler(request, reply)
242:   }
243: }
244: 
245: function rawBody (request, reply, options, parser, done) {
246:   const asString = parser.asString === true
247:   const limit = options.limit === null ? parser.bodyLimit : options.limit
248:   const contentLength = Number(request.headers['content-length'])
249: 
250:   if (contentLength > limit) {
251:     done(new FST_ERR_CTP_BODY_TOO_LARGE(), undefined)
252:     return
253:   }
254: 
255:   let receivedLength = 0
256:   const chunks = []
257:   const payload = request[kRequestPayloadStream] || request.raw
258: 
259:   // Always read raw Buffers and decode once at the end: setEncoding() would
260:   // allocate a StringDecoder per request and force a Buffer.byteLength()
261:   // rescan of every decoded chunk just to enforce the byte limit.
262: 
263:   payload.on('data', onData)
264:   payload.on('end', onEnd)
265:   payload.on('error', onEnd)
266:   payload.resume()
267: 
268:   function onData (chunk) {
269:     // A custom preParsing stream may still emit strings
270:     if (typeof chunk === 'string') {
271:       chunk = Buffer.from(chunk)
272:     }
273:     receivedLength += chunk.length
274:     const { receivedEncodedLength = 0 } = payload
275:     // The resulting body length must not exceed bodyLimit (see "zip bomb").
276:     // The case when encoded length is larger than received length is rather theoretical,
277:     // unless the stream returned by preParsing hook is broken and reports wrong value.
278:     if (receivedLength > limit || receivedEncodedLength > limit) {
279:       payload.removeListener('data', onData)
280:       payload.removeListener('end', onEnd)
281:       payload.removeListener('error', onEnd)
282:       done(new FST_ERR_CTP_BODY_TOO_LARGE(), undefined)
283:       return
284:     }
285: 
286:     chunks.push(chunk)
287:   }
288: 
289:   function onEnd (err) {
290:     payload.removeListener('data', onData)
291:     payload.removeListener('end', onEnd)
292:     payload.removeListener('error', onEnd)
293: 
294:     if (err != null) {
295:       if (!(typeof err.statusCode === 'number' && err.statusCode >= 400)) {
296:         err.statusCode = 400
297:       }
298:       done(err, undefined)
299:       return
300:     }
301: 
302:     if (!Number.isNaN(contentLength) && (payload.receivedEncodedLength || receivedLength) !== contentLength) {
303:       done(new FST_ERR_CTP_INVALID_CONTENT_LENGTH(), undefined)
304:       return
305:     }
306: 
307:     let body
308:     if (asString) {
309:       // Decoding the whole body at once also keeps multi-byte characters
310:       // split across chunks intact
311:       body = chunks.length === 1
312:         ? chunks[0].toString('utf8')
313:         : Buffer.concat(chunks, receivedLength).toString('utf8')
314:     } else {
315:       // Always copy so the parser never receives a view over the shared
316:       // socket read buffer
317:       body = Buffer.concat(chunks, receivedLength)
318:     }
319: 
320:     const result = parser.fn(request, body, done)
321:     if (result && typeof result.then === 'function') {
322:       result.then(body => { done(null, body) }, done)
323:     }
324:   }
325: }
326: 
327: function getDefaultJsonParser (onProtoPoisoning, onConstructorPoisoning) {
328:   const parseOptions = { protoAction: onProtoPoisoning, constructorAction: onConstructorPoisoning }
329: 
330:   return defaultJsonParser
331: 
332:   function defaultJsonParser (req, body, done) {
333:     if (body.length === 0) {
334:       done(new FST_ERR_CTP_EMPTY_JSON_BODY(), undefined)
335:       return
336:     }
337:     try {
338:       done(null, secureJsonParse(body, parseOptions))
339:     } catch {
340:       done(new FST_ERR_CTP_INVALID_JSON_BODY(), undefined)
341:     }
342:   }
343: }
344: 
345: function defaultPlainTextParser (req, body, done) {
346:   done(null, body)
347: }
348: 
349: function Parser (asString, asBuffer, bodyLimit, fn) {
350:   this.asString = asString
351:   this.asBuffer = asBuffer
352:   this.bodyLimit = bodyLimit
353:   this.fn = fn
354: }
355: 
356: function buildContentTypeParser (c) {
357:   const contentTypeParser = new ContentTypeParser()
358:   contentTypeParser[kDefaultJsonParse] = c[kDefaultJsonParse]
359:   contentTypeParser.customParsers = new Map(c.customParsers.entries())
360:   contentTypeParser.parserList = c.parserList.slice()
361:   contentTypeParser.parserRegExpList = c.parserRegExpList.slice()
362:   return contentTypeParser
363: }
364: 
365: function addContentTypeParser (contentType, opts, parser) {
366:   if (this[kState].started) {
367:     throw new FST_ERR_CTP_INSTANCE_ALREADY_STARTED('addContentTypeParser')
368:   }
369: 
370:   if (typeof opts === 'function') {
371:     parser = opts
372:     opts = {}
373:   }
374: 
375:   if (!opts) opts = {}
376:   if (!opts.bodyLimit) opts.bodyLimit = this[kBodyLimit]
377: 
378:   if (Array.isArray(contentType)) {
379:     contentType.forEach((type) => this[kContentTypeParser].add(type, opts, parser))
380:   } else {
381:     this[kContentTypeParser].add(contentType, opts, parser)
382:   }
383: 
384:   return this
385: }
386: 
387: function hasContentTypeParser (contentType) {
388:   return this[kContentTypeParser].hasParser(contentType)
389: }
390: 
391: function removeContentTypeParser (contentType) {
392:   if (this[kState].started) {
393:     throw new FST_ERR_CTP_INSTANCE_ALREADY_STARTED('removeContentTypeParser')
394:   }
395: 
396:   if (Array.isArray(contentType)) {
397:     for (const type of contentType) {
398:       this[kContentTypeParser].remove(type)
399:     }
400:   } else {
401:     this[kContentTypeParser].remove(contentType)
402:   }
403: }
404: 
405: function removeAllContentTypeParsers () {
406:   if (this[kState].started) {
407:     throw new FST_ERR_CTP_INSTANCE_ALREADY_STARTED('removeAllContentTypeParsers')
408:   }
409: 
410:   this[kContentTypeParser].removeAll()
411: }
412: 
413: function validateRegExp (regexp) {
414:   // RegExp should either start with ^ or include ;?
415:   // It can ensure the user is properly detect the essence
416:   // MIME types.
417:   if (regexp.source[0] !== '^' && regexp.source.includes(';?') === false) {
418:     FSTSEC001(regexp.source)
419:   }
420: }
421: 
422: module.exports = ContentTypeParser
423: module.exports.helpers = {
424:   buildContentTypeParser,
425:   addContentTypeParser,
426:   hasContentTypeParser,
427:   removeContentTypeParser,
428:   removeAllContentTypeParsers
429: }
430: module.exports.defaultParsers = {
431:   getDefaultJsonParser,
432:   defaultTextParser: defaultPlainTextParser
433: }
434: module.exports[kTestInternals] = { rawBody }
